"\"\"\"Configuration loading and device management utilities.\"\"\"\nimport yaml\nimport torch\nimport logging\nfrom pathlib import Path\nfrom typing import Any, Dict, Optional\n\nlogger = logging.getLogger(__name__)\n\n\ndef load_config(config_path: str) -> Dict[str, Any]:\n    \"\"\"Load a YAML configuration file.\n\n    Args:\n        config_path: Path to the YAML config file.\n\n    Returns:\n        Dictionary with configuration values.\n\n    Raises:\n        FileNotFoundError: If config file does not exist.\n        ValueError: If config file is not valid YAML.\n    \"\"\"\n    path = Path(config_path)\n    if not path.exists():\n        raise FileNotFoundError(f\"Config file not found: {config_path}\")\n    if path.suffix not in (\".yaml\", \".yml\"):\n        raise ValueError(f\"Expected YAML file, got: {path.suffix}\")\n\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        config = yaml.safe_load(f)\n\n    if config is None:\n        raise ValueError(f\"Config file is empty: {config_path}\")\n\n    logger.info(f\"Loaded config from {config_path}\")\n    return config\n\n\ndef get_device(device_str: str = \"auto\") -> torch.device:\n    \"\"\"Resolve the compute device.\n\n    Args:\n        device_str: One of 'auto', 'cpu', 'cuda', or 'cuda:N'.\n\n    Returns:\n        torch.device instance.\n    \"\"\"\n    if device_str == \"auto\":\n        return torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n    return torch.device(device_str)\n\n\ndef set_global_seed(seed: int) -> None:\n    \"\"\"Set global random seeds for reproducibility.\n\n    Covers Python random, NumPy, and PyTorch (CPU + GPU).\n    \"\"\"\n    import random\n    import numpy as np\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed_all(seed)\n        torch.backends.cudnn.deterministic = True\n        torch.backends.cudnn.benchmark = False\n    logger.debug(f\"Global seed set to {seed}\")\n"